#!/usr/bin/env python3
"""fiber_srcgeom: the 6-source chain fits a footprint generated by a chain, and the shared-geometry z
tells one place from two.

  1. A template made by a 6-source chain (random currents summing to zero) on a staggered octrode is
     refitted to its noise level.
  2. Two templates from ONE geometry with DIFFERENT currents (a cell's spike-to-spike change) share a
     geometry at small z.
  3. Negative control: the same currents from a geometry 80 um deeper give a large z (the test is about
     place, not shape).  The resolution is coarse -- measured here: 10/20/40/80 um in depth -> z 2.4 /
     0.9 / 2.2 / 5.1; 20/40 um laterally -> 0.1 / 0.3 (not resolved).  See the module docstring.
Exits nonzero on failure.
"""
import os
import sys

import numpy as np

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src"))
from fiber_kit import fiber_srcgeom as sg  # noqa: E402

fails = 0


def check(name, ok, detail=""):
    global fails
    print(f"  [{'PASS' if ok else 'FAIL'}] {name}" + (f": {detail}" if detail and not ok else ""))
    fails += 0 if ok else 1


rng = np.random.default_rng(0)
xy = np.array([[0, 0], [12, 20], [-12, 40], [12, 60], [-12, 80], [12, 100], [-12, 120], [12, 140]], float)
S = sg.sites3(xy)
tt = np.arange(42)


def currents(seed):
    r = np.random.default_rng(seed)
    I = np.zeros((42, len(sg.OFFSETS)))
    for m in range(len(sg.OFFSETS)):
        I[:, m] = r.normal(0, 1) * np.exp(-0.5 * ((tt - 20 - r.uniform(-2, 2)) / r.uniform(1, 3)) ** 2)
    return I - I.mean(1, keepdims=True)                    # charge conservation


def template(th, I, noise, seed):
    X = I @ sg.transfer(th, S).T
    X = X / np.abs(X).max() * 100
    return X + np.random.default_rng(seed).normal(0, noise, X.shape)


thA = np.array([0.0, 60.0, 20.0, 0.2, 0.3, 30.0])
thB = thA.copy(); thB[1] += 80.0
NOISE = 0.5                                                 # template noise (a mean of many spikes)
X1 = template(thA, currents(1), NOISE, 10)
_, m = sg.fit(X1, S)
nz = NOISE ** 2 * X1.size / (X1 ** 2).sum()
check("a chain-made template is refitted to ~ its noise", m < 3 * nz, f"misfit {m:.2e} vs noise {nz:.2e}")
X2 = template(thA, currents(1) * 0.7 + 0.3 * currents(2), NOISE, 11)
z_same, _, _ = sg.shared_geometry_z(X1, X2, S, nz, nz)
X3 = template(thB, currents(1), NOISE, 12)
z_diff, _, _ = sg.shared_geometry_z(X1, X3, S, nz, nz)
check("one place, different currents: small z", z_same < 2.0, f"z {z_same:.2f}")
check("negative control: two places 80 um apart in depth: large z", z_diff > 4.0 and z_diff > 5 * max(z_same, 0.1),
      f"z {z_diff:.2f} vs {z_same:.2f}")
print("OK (0 failures)" if not fails else f"FAILED ({fails})")
sys.exit(1 if fails else 0)
